import React, { FunctionComponent, ReactElement } from "react";
import { withKnobs, text, select } from "@storybook/addon-knobs";
import { Badge } from "@cockroachlabs/ui-components";
import { StoryContainer, StoryDescription } from "./layout";

export default {
  title: "Badge",
  components: Badge,
  decorators: [withKnobs],
};

const BadgeDisplaySection: FunctionComponent<{
  children: Array<ReactElement | null>;
}> = ({ children }) => (
  <section style={{ display: "flex", justifyContent: "flex-start" }}>
    {children}
  </section>
);
const BadgeDisplay: FunctionComponent<{
  children: Array<ReactElement | null>;
}> = ({ children }) => (
  <div style={{ margin: "0rem 1rem", textAlign: "center" }}>{children}</div>
);
const Label: FunctionComponent<{
  children: string;
}> = ({ children }) => (
  <div style={{ marginBottom: "1rem" }}>
    <code>{children}</code>
  </div>
);

export const Example = () => (
  <StoryContainer>
    <h1>Badges</h1>

    <StoryDescription>
      Use badges to visually label UI objects for quick recognition, status
      indication or navigation. Badges can be all-caps or lowercase. There are 5
      badge intents:
      <ul>
        <li>
          {" "}
          <strong>Neutral:</strong> Use to indicate a default state{" "}
        </li>
        <li>
          {" "}
          <strong>Success:</strong> Use to indicate a successful state{" "}
        </li>
        <li>
          {" "}
          <strong>Warning:</strong> Use to indicate that there is something that
          requires attention{" "}
        </li>
        <li>
          {" "}
          <strong>Danger:</strong> Use to indicate a failed state.{" "}
        </li>
        <li>
          {" "}
          <strong>Info:</strong> Use to indicate useful information.{" "}
        </li>
      </ul>
    </StoryDescription>

    <section>
      <h4>Intents</h4>
      <BadgeDisplaySection>
        <BadgeDisplay>
          <Label>neutral</Label>
          <Badge intent="neutral">this is fine</Badge>
        </BadgeDisplay>
        <BadgeDisplay>
          <Label>success</Label>
          <Badge intent="success">Complete</Badge>
        </BadgeDisplay>
        <BadgeDisplay>
          <Label>warning</Label>
          <Badge intent="warning">Caution</Badge>
        </BadgeDisplay>
        <BadgeDisplay>
          <Label>danger</Label>
          <Badge intent="danger">Error</Badge>
        </BadgeDisplay>
        <BadgeDisplay>
          <Label>info</Label>
          <Badge intent="info">Info</Badge>
        </BadgeDisplay>
      </BadgeDisplaySection>
    </section>

    <section>
      <h4>Transform Case</h4>
      <BadgeDisplaySection>
        <BadgeDisplay>
          <Label>uppercase</Label>
          <Badge transformCase="uppercase">Caps</Badge>
        </BadgeDisplay>
        <BadgeDisplay>
          <Label>none</Label>
          <Badge transformCase="none">v10.3.7-Alpha.0876b</Badge>
        </BadgeDisplay>
      </BadgeDisplaySection>
    </section>
  </StoryContainer>
);

export const Demo = () => (
  <StoryContainer>
    <Badge
      intent={select(
        "Intent",
        ["neutral", "success", "warning", "danger", "info"],
        "neutral",
      )}
      transformCase={select(
        "Transform Case",
        ["uppercase", "none"],
        "uppercase",
      )}
    >
      {text("Text", "badge")}
    </Badge>
  </StoryContainer>
);

import React, { FunctionComponent } from "react";
import classNames from "classnames/bind";

import objectToClassnames from "../utils/objectToClassnames";

import styles from "./Badge.module.scss";

export type BadgeCase = "none" | "uppercase";
export type BadgeIntent = "neutral" | "success" | "warning" | "danger" | "info";

interface OwnBadgeProps {
  intent?: BadgeIntent;
  transformCase?: BadgeCase;
  debug?: boolean;
}
type NativeDivProps = Omit<
  React.HTMLAttributes<HTMLDivElement>,
  keyof OwnBadgeProps
>;

export type BadgeProps = NativeDivProps & OwnBadgeProps;

const cx = classNames.bind(styles);

export const Badge: FunctionComponent<BadgeProps> = ({
  intent = "neutral",
  transformCase = "uppercase",
  debug = false,
  children,
  className,
  ...props
}) => {
  const classnames = cx(
    "badge",
    objectToClassnames({ intent, transformCase }),
    className,
  );

  if (children !== undefined) {
    return (
      <div className={classnames} {...props}>
        {debug && (
          <pre>
            intent :: {intent}
            transformCase :: {transformCase}
          </pre>
        )}
        {children}
      </div>
    );
  }

  return null;
};

export default Badge;

@import "../styles/tokens.scss";

.badge {
  border-radius: 3px;
  display: inline-block;
  font-size: 12px;
  line-height: 14px;
  padding: crl-gutters(0.625) crl-gutters(1);
  vertical-align: crl-gutters(0.5);
  text-align: center;
  white-space: nowrap;
}

.intent-neutral {
  background: $component-badge-background-color-neutral;
  color: $component-badge-font-color-neutral;
}

.intent-success {
  background: $component-badge-background-color-success;
  color: $component-badge-font-color-success;
}

.intent-warning {
  background: $component-badge-background-color-warning;
  color: $component-badge-font-color-warning;
}

.intent-danger {
  background: $component-badge-background-color-danger;
  color: $component-badge-font-color-danger;
}

.intent-info {
  background: $component-badge-background-color-info;
  color: $component-badge-font-color-info;
}

.noTransform {
  text-transform: none;
}

.transformCase-none {
  text-transform: none;
}

.transformCase-uppercase {
  text-transform: uppercase;
}

// const classnames = classnames("component", propsToClassNames({ prop1, prop2, prop3 }));
// "[prop1 name]--[prop1 value] [prop2 name]--[prop2 value] [prop3 name]--[prop3 value]";

const objectToClassNames = (
  obj: { [key: string]: string },
  delimiter = "-",
): string[] =>
  Object.keys(obj).reduce(
    (acc, key) => [`${key}${delimiter}${obj[key]}`, ...acc],
    [],
  );

export default objectToClassNames;

@import "@cockroachlabs/design-tokens/dist/web/_tokens.scss";

/**
 Variables
*/
// This variable reflects the base gutter value
// specified by our design system.
$crl-gutters: 8px;
$crl-border-radius: 3px;
$crl-input-height: 40px;
$crl-input-height-small: 24px;
$crl-transition-duration: 0.15s;

/**
 Mixins
*/
@mixin crl-depth($n_: 1, $color_: $color-core-blue-5) {
  /**
      Desc:
        This mixin sets the `box-shadow` property
        to reflect the depth layers outlined in the
        CRL design system.

      Example usage:
        `@include depth(3);`
    */
  $depth-1: 0 1px 5px 0px rgba($color_, 0.17);
  $depth-2: 0 6px 15px 0px rgba($color_, 0.17);
  $depth-3: 0 9px 20px 0px rgba($color_, 0.27);
  $depth-4: 0 10px 40px 0px rgba($color_, 0.37);

  @if $n_ == 1 {
    -webkit-box-shadow: $depth-1;
    -moz-box-shadow: $depth-1;
    box-shadow: $depth-1;
  } @else if $n_ == 2 {
    -webkit-box-shadow: $depth-2;
    -moz-box-shadow: $depth-2;
    box-shadow: $depth-2;
  } @else if $n_ == 3 {
    -webkit-box-shadow: $depth-3;
    -moz-box-shadow: $depth-3;
    box-shadow: $depth-3;
  } @else if $n_ == 4 {
    -webkit-box-shadow: $depth-4;
    -moz-box-shadow: $depth-4;
    box-shadow: $depth-4;
  } @else {
    box-shadow: none;
  }
}

@mixin crl-transition($props_...) {
  /**
    Desc:
      Helper for maintaining consistent transitions.
    Example usage:
      ```
      .my-css-class {
        @include crl-transition(color, border-color, height);
      }
      ```
  */
  transition-property: $props_;
  transition-duration: $crl-transition-duration;
  transition-timing-function: ease-in-out;
}

@mixin crl-box-shadow($offset_h_, $offset_v_, $blur_, $spread_, $color_) {
  /**
    Desc:
      Helper for cross-browser box-shadows.
    Example usage:
      ```
      .my-css-class {
        @include crl-box-shadows(0, 2px, 4px, 0, $crl-blue-5);
      }
      ```
  */
  -webkit-box-shadow: $offset_h_ $offset_v_ $blur_ $spread_ $color_;
  -moz-box-shadow: $offset_h_ $offset_v_ $blur_ $spread_ $color_;
  box-shadow: $offset_h_ $offset_v_ $blur_ $spread_ $color_;
}

@mixin firefox-only {
  @at-root {
    @-moz-document url-prefix() {
      & {
        @content;
      }
    }
  }
}

/**
 Variables
*/
// This variable reflects the base gutter value
// specified by our design system.
$crl-gutters: 8px;

/**
 Functions
*/
@function crl-lighten($color) {
  /**
    Desc:
      Helper for consistent lightening of default tone,
      for example in lightening a button in a disabled state.

    Example usage:
      ```
      .my-css-class {
        background-color: crl-lighten($crl-base-green);
      }
      ```
  */
  @return mix(white, $color, 95%);
}

@function crl-darken($color) {
  /**
    Desc:
      Helper for consistent darkening of default tone,
      for example in darkening a button in a hovered or active state.

    Example usage:
      ```
      .my-css-class {
        background-color: crl-darken($crl-base-green);
      }
      ```
  */
  @return mix(black, $color, 10%);
}

@function crl-gutters($n_: 1) {
  /**
    Desc:
      Use this function when spacing elements to preserve
      consistent spacing in multiples of our gutter value
      established in the CRL design system.

      Only use explict values (e.g. `margin: 5px;`) in CSS
      when setting a one-off value that is used for fine-tuning
      an element position (e.g. such as aligning an SVG icon).

    Example usage:
      ```
      .my-css-class {
        padding-top: crl-gutters(3);
        margin-bottom: crl-gutters(1);
      }
      ```
  */
  @if $n_ {
    @return $n_ * $crl-gutters;
  } @else {
    @return 0;
  }
}
